import{_ as e,o as t,c as r,a2 as a}from"./chunks/framework.BZO4qERu.js";const g=JSON.parse('{"title":"Discord","description":"","frontmatter":{},"headers":[],"relativePath":"ja/integrations/channels/discord.md","filePath":"ja/integrations/channels/discord.md","lastUpdated":1792323081000}'),l={name:"ja/integrations/channels/discord.md"};function i(s,o,d,n,c,h){return t(),r("div",null,[...o[0]||(o[0]=[a('<h1 id="discord" tabindex="-1">Discord <a class="header-anchor" href="#discord" aria-label="Permalink to &quot;Discord&quot;">​</a></h1><p>Memoh Bot を Discord につなぎ、サーバーに参加して、チャンネルや DM でコミュニティのメンバーと会話できるようにします。</p><h2 id="前提条件" tabindex="-1">前提条件 <a class="header-anchor" href="#前提条件" aria-label="Permalink to &quot;前提条件&quot;">​</a></h2><ul><li><a href="https://discord.com/developers/applications" target="_blank" rel="noreferrer">Discord Developer Portal</a> にログインできる Discord アカウント。</li><li>Bot の参加を承認できるサーバー。</li><li>Memoh Bot。チャネルはその <strong>プラットフォーム</strong> タブで設定します。</li></ul><h2 id="手順" tabindex="-1">手順 <a class="header-anchor" href="#手順" aria-label="Permalink to &quot;手順&quot;">​</a></h2><h3 id="_1-discord-developer-portal-でアプリケーションを作成し、bot-token-を取得する" tabindex="-1">1. Discord Developer Portal でアプリケーションを作成し、Bot Token を取得する <a class="header-anchor" href="#_1-discord-developer-portal-でアプリケーションを作成し、bot-token-を取得する" aria-label="Permalink to &quot;1. Discord Developer Portal でアプリケーションを作成し、Bot Token を取得する&quot;">​</a></h3><ol><li><a href="https://discord.com/developers/applications" target="_blank" rel="noreferrer">Discord Developer Portal</a> を開きます。</li><li><strong>New Application</strong> をクリックし、名前を付けます。</li><li>左側のメニューから <strong>Bot</strong> に移動します。</li><li><strong>Reset Token</strong> をクリックして <strong>Bot Token</strong> を生成し、コピーして安全に保管します。</li></ol><h3 id="_2-discord-developer-portal-で特権インテントを有効にする" tabindex="-1">2. Discord Developer Portal で特権インテントを有効にする <a class="header-anchor" href="#_2-discord-developer-portal-で特権インテントを有効にする" aria-label="Permalink to &quot;2. Discord Developer Portal で特権インテントを有効にする&quot;">​</a></h3><ol><li><strong>Bot</strong> ページを下にスクロールし、<strong>Privileged Gateway Intents</strong> を見つけます。</li><li><code>Message Content Intent</code>、<code>Server Members Intent</code>、<code>Presence Intent</code> を有効にします。</li><li>保存します。</li></ol><h3 id="_3-discord-developer-portal-で招待リンクを生成し、bot-をサーバーに追加する" tabindex="-1">3. Discord Developer Portal で招待リンクを生成し、Bot をサーバーに追加する <a class="header-anchor" href="#_3-discord-developer-portal-で招待リンクを生成し、bot-をサーバーに追加する" aria-label="Permalink to &quot;3. Discord Developer Portal で招待リンクを生成し、Bot をサーバーに追加する&quot;">​</a></h3><ol><li><strong>OAuth2</strong> &gt; <strong>URL Generator</strong> に移動します。</li><li>scope の <code>bot</code> と <code>applications.commands</code> にチェックを入れます。</li><li>権限の <code>Send Messages</code>、<code>Read Message History</code>、<code>Embed Links</code>、<code>Attach Files</code> にチェックを入れます。</li><li>生成された URL をコピーし、ブラウザで開きます。</li><li>追加先のサーバーを選択して承認します。</li></ol><blockquote><p>公式ガイド：<a href="https://discord.com/developers/docs/intro" target="_blank" rel="noreferrer">Discord Developer Portal - Bots</a></p></blockquote><h3 id="_4-memoh-で-discord-チャネルを追加する" tabindex="-1">4. Memoh で Discord チャネルを追加する <a class="header-anchor" href="#_4-memoh-で-discord-チャネルを追加する" aria-label="Permalink to &quot;4. Memoh で Discord チャネルを追加する&quot;">​</a></h3><ol><li>Bot の詳細ページを開き、<strong>プラットフォーム</strong> タブに移動します。</li><li><strong>Add Channel</strong> をクリックし、<strong>Discord</strong> を選択します。</li><li><strong>Bot Token</strong> を貼り付けます。</li><li><strong>Save and Enable</strong> をクリックします。</li></ol><h2 id="認証情報" tabindex="-1">認証情報 <a class="header-anchor" href="#認証情報" aria-label="Permalink to &quot;認証情報&quot;">​</a></h2><table tabindex="0"><thead><tr><th>フィールド</th><th>説明</th></tr></thead><tbody><tr><td><strong>Bot Token</strong></td><td>アプリケーションの <strong>Bot</strong> ページで <strong>Reset Token</strong> により生成します。安全に保管してください。</td></tr></tbody></table><h2 id="動作確認" tabindex="-1">動作確認 <a class="header-anchor" href="#動作確認" aria-label="Permalink to &quot;動作確認&quot;">​</a></h2><p>Bot に DM で <code>/help</code> を送るか、Bot が参加しているサーバーのチャンネルで @メンションします。Bot がコマンド一覧を返せば、チャネルは機能しています。</p><h2 id="グループチャット" tabindex="-1">グループチャット <a class="header-anchor" href="#グループチャット" aria-label="Permalink to &quot;グループチャット&quot;">​</a></h2><p>Discord ではサーバーがグループチャットに相当します。Bot の参加を承認したあと、チャンネルで @メンションすると会話できます。</p><h2 id="無効化と認証情報の更新" tabindex="-1">無効化と認証情報の更新 <a class="header-anchor" href="#無効化と認証情報の更新" aria-label="Permalink to &quot;無効化と認証情報の更新&quot;">​</a></h2><p>Bot の <strong>プラットフォーム</strong> タブから、いつでもこのチャネルを無効化・削除できます。token を更新するときは、<strong>Bot Token</strong> フィールドを更新して保存してください。</p>',22)])])}const b=e(l,[["render",i]]);export{g as __pageData,b as default};
